/**
 * Time-of-day patterns: "the AUD/JPY OTC candle at 05:20 has closed green
 * on 26 of the last 30 days". OTC prices are generated by the broker, so the
 * same minute can repeat its color from day to day. This finds those minutes
 * and turns them into advance predictions for the coming hour.
 *
 * Strict on purpose: 1,440 minutes x several pairs are checked, so a few
 * minutes will look one-sided by pure chance. A minute only counts when even
 * a cautious estimate (Wilson, z = 3.3) beats break-even AND the most recent
 * third of the days agrees.
 */
import type { Bar, Dir } from "./detect.ts";
import { breakEven, winRateFloor } from "./stats.ts";

export interface TimeSignal {
  /** Start of the predicted candle, ms. */
  start: number;
  dir: Dir;
  /** Days that candle closed in `dir` / days it closed green or red. */
  winRate: number;
  wins: number;
  n: number;
  floor: number;
  /** Same, for the newest third of the days. */
  recent: { n: number; winRate: number };
}

export const TIME_Z = 3.3;
export const MIN_DAYS = 14;

const DAY = 86_400_000;

/** Minute of the (UTC) day, 0..1439. */
const minuteOfDay = (t: number) => Math.floor((t % DAY) / 60_000);

/**
 * Colors per minute of the day from 1-minute candles: index = minute, value =
 * list of +1 (green) / -1 (red) in time order (flat candles skipped).
 */
export function colorsByMinute(bars: Bar[]): Int8Array[] {
  const tmp: number[][] = Array.from({ length: 1440 }, () => []);
  for (const b of bars) {
    if (b.time % 60_000 !== 0) continue;
    const c = b.close > b.open ? 1 : b.close < b.open ? -1 : 0;
    if (c) tmp[minuteOfDay(b.time)].push(c);
  }
  return tmp.map((l) => Int8Array.from(l));
}

/** Days of 1-minute history covered (roughly). */
export const daysCovered = (bars: Bar[]) => (bars.length ? (bars[bars.length - 1].time - bars[0].time) / DAY : 0);

/**
 * Advance predictions for candles starting in [fromMs, toMs).
 * `byMinute` = colorsByMinute(bars) (pass it in to compute it once).
 */
export function timeSignals(byMinute: Int8Array[], fromMs: number, toMs: number, payout: number, z = TIME_Z): TimeSignal[] {
  const be = breakEven(payout);
  const out: TimeSignal[] = [];
  const first = Math.ceil(fromMs / 60_000) * 60_000;
  for (let t = first; t < toMs; t += 60_000) {
    const list = byMinute[minuteOfDay(t)];
    const n = list.length;
    if (n < MIN_DAYS) continue;
    let ups = 0;
    for (let k = 0; k < n; k++) if (list[k] > 0) ups++;
    const dir: Dir = ups * 2 >= n ? "up" : "down";
    const wins = dir === "up" ? ups : n - ups;
    const floor = winRateFloor(wins, n, z);
    if (floor <= be) continue;
    const cut = n - Math.max(5, Math.floor(n / 3));
    let rw = 0;
    for (let k = cut; k < n; k++) if ((list[k] > 0) === (dir === "up")) rw++;
    const recent = { n: n - cut, winRate: rw / (n - cut) };
    if (recent.winRate <= be) continue;
    out.push({ start: t, dir, winRate: wins / n, wins, n, floor, recent });
  }
  return out;
}
